 7	final class GraphComponentFinder {
 8	
 9	    private GraphComponentFinder() {
10	    }
11	
12	    static ConnectedComponentsResult findConnectedComponents(Graph graph) {
13	        Objects.requireNonNull(graph, "graph");
14	
15	        int vertexCount = graph.vertexCount();
16	        validateVertexCount(vertexCount);
17	        boolean[] visited = new boolean[vertexCount];
18	        List<ConnectedComponent> components = new ArrayList<>();
19	
20	        for (Vertex vertex : graph.vertices()) {
21	            if (!visited[vertex.index()]) {
22	                components.add(traverseComponent(graph, vertex, vertexCount, visited));
23	            }
24	        }
25	
26	        return new ConnectedComponentsResult(components);
27	    }
28	
29	    private static ConnectedComponent traverseComponent(
30	            Graph graph,
31	            Vertex startVertex,
32	            int vertexCount,
33	            boolean[] visited) {
34	        Queue<Vertex> pendingVertices = new ArrayDeque<>();
35	        List<Vertex> component = new ArrayList<>();
36	
37	        visited[startVertex.index()] = true;
38	        pendingVertices.add(startVertex);
39	
40	        while (!pendingVertices.isEmpty()) {
41	            Vertex currentVertex = pendingVertices.remove();
42	            component.add(currentVertex);
43	
44	            for (Vertex neighbor : graph.neighborsOf(currentVertex)) {
45	                validateNeighborVertex(neighbor, vertexCount);
46	                if (!visited[neighbor.index()]) {
47	                    visited[neighbor.index()] = true;
48	                    pendingVertices.add(neighbor);
49	                }
50	            }
51	        }
52	
53	        return new ConnectedComponent(component);
54	    }
55	
56	    private static void validateVertexCount(int vertexCount) {
57	        if (vertexCount < 0) {
58	            throw new IllegalArgumentException("Vertex count must be non-negative.");
59	        }
60	    }
61	
62	    private static void validateNeighborVertex(Vertex vertex, int vertexCount) {
63	        if (vertex == null) {
64	            throw new IllegalArgumentException("Neighbor vertex must not be null.");
65	        }
66	        if (vertex.index() < 0 || vertex.index() >= vertexCount) {
67	            throw new IllegalArgumentException("Neighbor index out of bounds: " + vertex.index());
68	        }
69	    }
70	}

